import {CalendarRange, IndexPath} from '@ui-kitten/components';
import {create} from 'zustand';

type ValueFilterSearch = {
  typeReceipt?: IndexPath;
  paymentMethod?: IndexPath;
  receiptStatus?: IndexPath;
  rangeDay: CalendarRange<Date>;
  isCustomDay?: boolean;
};
interface ZutandStore {
  valueFilterSearch: ValueFilterSearch;
  setValueFilterSearch: (valueFilterSearch: ValueFilterSearch) => void;
}

const initialReceiptState = {
  valueFilterSearch: {
    rangeDay: {startDate: new Date(), endDate: new Date()},
  },
};

export const useReceiptZustandStore = create<ZutandStore>((set, get) => ({
  ...initialReceiptState,
  setValueFilterSearch: (valueFilterSearch: ValueFilterSearch) => {
    set({valueFilterSearch});
  },
}));
