import {
  FlatList,
  ScrollView,
  Text,
  TouchableOpacity,
  useWindowDimensions,
  View,
} from 'react-native';
import {Icon} from '@ui-kitten/components';
import {useEffect, useState} from 'react';
import {Color, Font, NavigationName} from '../../../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {styles} from './styles';
import Toast from 'react-native-toast-message';
import {t} from 'i18next';
import {useNavigation} from '@react-navigation/native';
import LoadingMore from '../../../../../../components/LoadingMore';
import TextCM from '../../../../../../components/Text';
type Receipt = {
  id: string;
  title: string;
  code: string;
  date: string;
  referenceCode: string;
  status: string;
  bank?: string;
  flagColor?: string;
  bgColor: string;
};

type Props = {
  status: 'lated' | 'inProgress' | 'complete' | 'draft';
};

const ListReceipt = ({status}: Props) => {
  const navigation = useNavigation();
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [typereceipt] = useState([
    {type: 'c', name: 'Biên lai C20, C21'},
    {type: 'r', name: 'Biên lai thu tiền'},
  ]);
  const [currentTypeReceipt, setCurrentTypeReceipt] = useState<'c' | 'r'>('c');
  const mockReceipts: Receipt[] = [
    {
      id: '1',
      title: 'Tạm thu - C848 - Nguyễn Văn A',
      code: '00003119',
      date: '19/05/2024',
      referenceCode: 'HCM-Q1-HS-123/2024/TAQ1',
      status: '---',
      flagColor: '#FF6B6B',
      bgColor: '#F2ECFD',
    },
    {
      id: '2',
      title: '{Tên biên lai}',
      code: '00003119',
      date: '19/05/2024',
      referenceCode: 'HCM-Q1-HS-123/2024/TAQ1',
      status: 'Ngân Hàng TMCP Phương Đông',
      flagColor: '#4A90E2',
      bgColor: '#FFF3EB',
    },
    {
      id: '3',
      title: 'Tạm thu - C848 - Nguyễn Văn A',
      code: '00003119',
      date: '19/05/2024',
      referenceCode: 'HCM-Q1-HS-123/2024/TAQ1',
      status: '---',
      flagColor: '#FF6B6B',
      bgColor: '',
    },
  ];

  const getDataReceipt = async () => {
    // Hàm lấy dữ liệu
    try {
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };

  useEffect(() => {
    // Khởi tạo load lấy dữ liệu
    getDataReceipt();
  }, []);

  const onRefresh = async () => {
    try {
      setIsFreshing(true);
      await getDataReceipt();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsFreshing(false);
    }
  };

  const navigateToDetailReceiptScreen = () => {
    navigation.navigate(NavigationName.DetailReceiptScreen as never);
  };

  const handleChangeTypeReceipt = (type: 'c' | 'r') => {
    setCurrentTypeReceipt(type);
    // Call các api khác để load loại data khác.
  };

  const handleLoadMore = async () => {
    setIsLoadMore(true);
    try {
      Toast.show({
        type: 'info',
        text1: t('CM.noti'),
        text2: 'Load thêm thông tin',
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsLoadMore(false);
    }
  };

  const DashLine = () => {
    return (
      <Svg height="20" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="10" rx="20" ry="8" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="10" rx="20" ry="8" fill="#f9fafe" />
        <Line
          x1="30"
          y1="10"
          x2={'93%'}
          y2="10"
          stroke="#f9fafe"
          strokeWidth="2"
          strokeDasharray="8"
        />
      </Svg>
    );
  };

  const renderReceiptItem = (receipt: Receipt) => {
    return (
      <TouchableOpacity
        onPress={navigateToDetailReceiptScreen}
        style={styles.container}>
        <View
          style={[
            styles.card,
            styles.radiusTop,
            styles.shadowTop,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.header}>
            <Text style={styles.title}>{receipt.title}</Text>
            <Icon name="flag" width={16} height={16} fill={receipt.flagColor} />
          </View>

          <Text style={styles.idNumber}>{receipt.code}</Text>
        </View>

        <DashLine />

        <View
          style={[
            styles.card,
            styles.radiusBot,
            styles.shadowBottom,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.receiptTypeSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.receiptTypeLabel}>Loại biên lai</Text>
            </View>
            <View style={{flex: 1}}>
              <Text style={styles.receiptTypeCode}>C20_THADS</Text>
            </View>
          </View>

          <View style={styles.dateSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.dateLabel}>Ngày tạo</Text>
            </View>
            <Text style={styles.dateValue}>17/08/2023 11:28</Text>
          </View>

          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <Text style={styles.statusLabel}>Trạng thái Biên lai</Text>
            </View>
            <View
              style={[styles.statusButton, {backgroundColor: receipt.bgColor}]}>
              <Text style={styles.statusButtonText}>Đang ký biên lai</Text>
            </View>
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  const renderTypeReceipt = (item: any) => {
    return (
      <TouchableOpacity
        key={item.type}
        onPress={() => handleChangeTypeReceipt(item.type)}
        style={styles.containerTypereceipt}>
        {currentTypeReceipt === item.type ? (
          <View style={styles.typeReceiptSelected}>
            <View
              style={{
                width: 8,
                height: 8,
                backgroundColor: Color.White,
                borderRadius: 10,
              }}></View>
          </View>
        ) : (
          <View style={styles.typeReceiptDefault}></View>
        )}
        <Text
          style={[
            styles.textTypeReceipt,
            {
              color: currentTypeReceipt === item.type ? '#262D34' : '#667085',
            },
          ]}>
          {item.name}
        </Text>
      </TouchableOpacity>
    );
  };

  return (
    <View style={{flex: 1, backgroundColor: '#f9fafe'}}>
      <View style={{flexDirection: 'row', gap: 16, marginBottom: 10}}>
        {typereceipt.map((item: any) => renderTypeReceipt(item))}
      </View>

      <FlatList
        // ref={refFlatList}
        showsVerticalScrollIndicator={false}
        style={{flex: 1}}
        data={mockReceipts}
        keyExtractor={index => '' + index.id}
        renderItem={({item}) => renderReceiptItem(item)}
        onEndReachedThreshold={0.5}
        onRefresh={onRefresh}
        refreshing={isRefreshing}
        onEndReached={handleLoadMore}
        ListEmptyComponent={() => (
          <View
            style={{
              alignItems: 'center',
              justifyContent: 'center',
              flex: 1,
            }}>
            <TextCM>{t('CM.emptyData')}</TextCM>
          </View>
        )}
        ListFooterComponent={() => isLoadMore && <LoadingMore />}
      />
    </View>
  );
};

export default ListReceipt;
