import {TabBar, TabView} from 'react-native-tab-view';
import {Color, Font} from '../../../../../constants';
import {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {StyleSheet, useWindowDimensions} from 'react-native';
import ListReceipt from './conponent/list-receipt';
type Route = {
  key: 'lated' | 'inProgress' | 'complete' | 'draft';
  title: string;
};
const RenderTabView = () => {
  const [index, setIndex] = useState(1);
  const {t} = useTranslation();
  const layout = useWindowDimensions();
  const routes: Route[] = [
    {key: 'lated', title: t('Trễ hạn')},
    {key: 'inProgress', title: t('Đang thực hiện')},
    {key: 'complete', title: t('Hoàn thành')},
    {key: 'draft', title: t('Nháp')},
  ];
  const renderTabBar = (props: any) => (
    <TabBar
      {...props}
      indicatorStyle={{backgroundColor: Color.BgPrimary}}
      style={{backgroundColor: Color.White}}
      scrollEnabled
      labelStyle={styles.labelTabbar}
      activeColor="#C83A1B"
    />
  );
  const renderScene = ({
    route,
  }: {
    route: {key: 'lated' | 'inProgress' | 'complete' | 'draft'};
  }) => {
    return <ListReceipt status={route.key} />;
  };
  return (
    <>
      <TabView
        lazy
        style={{backgroundColor: '#f9fafe'}}
        sceneContainerStyle={styles.sceneContainer}
        renderTabBar={renderTabBar}
        navigationState={{index, routes}}
        renderScene={renderScene}
        onIndexChange={setIndex}
        initialLayout={{width: layout.width}}
        swipeEnabled={false}
      />
    </>
  );
};
export default RenderTabView;

const styles = StyleSheet.create({
  labelTabbar: {
    color: '#00204DB2',
    fontFamily: Font.InterRegular400,
    fontSize: 14,
    textAlign: 'center',
  },
  sceneContainer: {
    paddingHorizontal: 16,
    paddingVertical: 10,
  },
});
