import {createBottomTabNavigator} from '@react-navigation/bottom-tabs';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import {TouchableOpacity, View} from 'react-native';
import {SizeDP} from '../../constants/Size';
import {
  IconDashboard,
  IconDashboardSelect,
  IconFollowTicket,
  IconFollowTicketSelect,
  IconHome,
  IconHomeSelect,
  IconMyReceipt,
  IconMyReceiptSelect,
  IconMyTicket,
  IconMyTicketSelect,
  IconNoti,
  IconNotification,
  IconNotificationSelect,
  IconNotiSelect,
  IconPlus,
  IconReceiptProcess,
  IconReceiptProcessSelect,
} from '../../assets/images';
import TextCM from '../../app/components/Text';
import {useTranslation} from 'react-i18next';
import {useEffect, useState} from 'react';
import {useAppDispatch} from '../../hooks/useRedux';
import {commonActions} from '../../redux/slices';
import {listBottomTab, TabName} from './helper';

const Tabs = createBottomTabNavigator();

const MyTabBar = ({state, navigation, t, totalRecoders}: any) => {
  return (
    <SafeAreaView
      edges={['bottom', 'left', 'right']}
      style={styles.ctnSafeTabBottom}>
      <View style={styles.ctnTabBottom}>
        {state.routes.map((route: any, index: number) => {
          let label = '';
          const isFocused = state.index === index;
          function getIcon() {
            switch (route.name) {
              case TabName.DashboardScreen:
                label = 'Thống kê';
                return (
                  <>
                    {isFocused ? (
                      <IconDashboardSelect
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    ) : (
                      <IconDashboard width={SizeDP(23)} height={SizeDP(20)} />
                    )}
                  </>
                );
              case TabName.MyReceiptScreen:
                label = 'Biên lai của tôi';
                return (
                  <>
                    {isFocused ? (
                      <IconMyReceiptSelect
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    ) : (
                      <IconMyReceipt width={SizeDP(23)} height={SizeDP(20)} />
                    )}
                  </>
                );
              case TabName.CreateNewScreen:
                label = '';
                return (
                  <>
                    <View
                      style={{
                        width: 38,
                        height: 38,
                        backgroundColor: '#C83A1B',
                        borderRadius: 10,
                        justifyContent: 'center',
                        alignItems: 'center',
                        shadowColor: '#C83A1B',
                        shadowOffset: {width: 0, height: 4},
                        shadowOpacity: 0.5, // 0x80 / 255 = ~0.5
                        shadowRadius: 8,
                        elevation: 6,
                      }}>
                      <IconPlus width={SizeDP(23)} height={SizeDP(20)} />
                    </View>
                  </>
                );
              case TabName.ReceiptProcessScreen:
                label = 'Biên lai xử lý';
                return (
                  <>
                    {isFocused ? (
                      <IconReceiptProcessSelect
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    ) : (
                      <IconReceiptProcess
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    )}
                  </>
                );
              case TabName.NotificationScreen:
                label = 'Thông báo';
                return (
                  <View style={{position: 'relative'}}>
                    {totalRecoders > 0 && (
                      <View
                        style={{
                          position: 'absolute',
                          backgroundColor: '#e14337',
                          borderRadius: 100,
                          paddingHorizontal: 4,
                          paddingVertical: 2,
                          top: -5,
                          right: totalRecoders > 100 ? -20 : -12,
                        }}>
                        <TextCM
                          style={{
                            fontSize: 10,
                            color: '#fff',
                          }}>
                          {totalRecoders < 100 ? totalRecoders : '99+'}
                        </TextCM>
                      </View>
                    )}
                    {isFocused ? (
                      <IconNotificationSelect
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    ) : (
                      <IconNotification
                        width={SizeDP(23)}
                        height={SizeDP(20)}
                      />
                    )}
                  </View>
                );

              default:
                break;
            }
          }

          const onPress = () => {
            const event = navigation.emit({
              type: 'tabPress',
              target: route.key,
              canPreventDefault: true,
            });

            if (!isFocused && !event.defaultPrevented) {
              navigation.navigate(route.name, route.params);
            }
          };

          return (
            <TouchableOpacity
              accessibilityRole="button"
              style={styles.ctnItemTabBottom}
              accessibilityState={isFocused ? {selected: true} : {}}
              key={index}
              onPress={onPress}>
              {getIcon()}
              <TextCM
                style={isFocused ? styles.txtLabelSelect : styles.txtLabel}>
                {label}
              </TextCM>
            </TouchableOpacity>
          );
        })}
      </View>
    </SafeAreaView>
  );
};
const BottomTabNavigationERequest = () => {
  const {t} = useTranslation();
  const dispatch = useAppDispatch();
  const [totalRecoders, setTotalRecoders] = useState(0);

  return (
    <Tabs.Navigator
      tabBar={props => (
        <MyTabBar {...props} t={t} totalRecoders={totalRecoders} />
      )}
      screenOptions={{headerShown: false}}>
      {listBottomTab?.map(item => {
        return (
          <Tabs.Screen
            key={item.name}
            name={item.name}
            component={item.component}
          />
        );
      })}
    </Tabs.Navigator>
  );
};

export default BottomTabNavigationERequest;
