import {Image, Text, View} from 'react-native';
import {styles} from './styles';
import {String} from '../../../../../constants';

type ProppsDetailItem = {
  icon: React.ReactElement;
  label: string;
  value?: any;
  isUser?: boolean;
};

const DetailItem = ({icon, label, value, isUser = false}: ProppsDetailItem) => {
  const UserAvatar = ({
    name,
    email,
    avatar,
  }: {
    name: string;
    email: string;
    avatar?: string;
  }) => (
    <View style={styles.avatarContainer}>
      <Image
        source={{
          uri: avatar || String.DEFAULT_IMAGE,
        }}
        style={styles.avatar}
      />
      <View style={styles.avatarTextContainer}>
        <View style={{flex: 1}}>
          <Text style={[styles.avatarName, {flex: 1}]}>{name}</Text>
        </View>
        <View style={{flex: 1}}>
          <Text style={styles.avatarEmail}>{email}</Text>
        </View>
      </View>
    </View>
  );
  return (
    <View style={styles.detailItem}>
      <View style={styles.detailIconLabel}>
        {icon}
        <Text style={styles.detailLabel}>{label}</Text>
      </View>

      {isUser ? (
        <UserAvatar name={value.name} email={value.email} />
      ) : typeof value === 'string' ? (
        <View style={{flex: 1}}>
          <Text style={styles.detailValue}>{value}</Text>
        </View>
      ) : (
        value
      )}
    </View>
  );
};
export default DetailItem;
