import React, {useCallback, useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {IconMyReceiptTopRight} from '../../../assets/images';
import {
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';

import RenderTabView from './component/tab-view';
import {Icon, Input} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import ModalFilter from './component/modal-filter';
import {debounce} from 'lodash';
import {styles} from './styles';
import {Color} from '../../../constants';

const MyReceiptScreen = () => {
  const {t} = useTranslation();
  const [value, setValue] = useState('');
  const [visibleFilter, setVisibleFilter] = useState(false);
  const handleSearch = async (querySearch: string) => {
    // call api, lọc dữ liệu ở đây, Dùng zustand sẽ dễ dàng hơn
    console.log('Chữ này xuất hiện khi ngừng gõ phím 0,3 giây:', querySearch);
  };
  const debouncedSearch = useCallback(debounce(handleSearch, 300), []);

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <View style={styles.ctn}>
        <HeaderCM
          title="MyReceipt"
          useLinearGradient={false}
          style={{backgroundColor: Color.BgPrimary}}
          contentStyle={{backgroundColor: Color.BgPrimary}}
          renderContentRight={() => (
            <TouchableOpacity onPress={() => false}>
              <IconMyReceiptTopRight width={20} height={20} />
            </TouchableOpacity>
          )}
        />
        <View style={styles.wrapInputSearch}>
          <Input
            allowFontScaling={false}
            style={styles.inputSearch}
            textStyle={{color: Color.Black}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('CM.search')}
            value={value}
            status="basic"
            // autoFocus
            onChangeText={nextValue => {
              setValue(nextValue);
              debouncedSearch(nextValue);
            }}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill={Color.White} />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={styles.wrapFilterIcon}>
            <Icon
              fill={Color.White}
              name="funnel-outline"
              width={25}
              height={25}
            />
          </TouchableOpacity>
        </View>
        <BottomSheetCM
          title={t('CM.filter')}
          onClose={() => setVisibleFilter(false)}
          isVisible={visibleFilter}
          renderContent={
            <ModalFilter onClose={() => setVisibleFilter(false)} />
          }
        />
        <RenderTabView />
      </View>
    </TouchableWithoutFeedback>
  );
};

export default MyReceiptScreen;
